mapper.select:
SELECT d.*
FROM documents d
WHERE d.workspace_id = #{workspaceId}
  AND d.deleted = false
  AND (
    EXISTS (
      SELECT 1
      FROM memberships m
      WHERE m.workspace_id = d.workspace_id
        AND m.user_id = #{userId}
    )
    OR EXISTS (
      SELECT 1
      FROM document_acl acl
      WHERE acl.workspace_id = d.workspace_id
        AND acl.document_id = d.id
        AND acl.principal_user_id = #{userId}
    )
  )


    AND LOWER(d.title) LIKE #{queryPattern}


    AND (LOWER(d.title) LIKE #{queryPattern} OR LOWER(COALESCE(d.body_text, '')) LIKE #{queryPattern})



  AND d.created_by = #{createdBy}


  AND d.updated_by = #{updatedBy}


  AND d.updated_at >= #{fromDate}


  AND d.updated_at <= #{toDate}


  AND d.id IN (
    WITH RECURSIVE subtree AS (
      SELECT id
      FROM documents
      WHERE workspace_id = #{workspaceId}
        AND id = #{scopePageId}
        AND deleted = false
      UNION ALL
      SELECT child.id
      FROM documents child
      JOIN subtree s ON child.parent_document_id = s.id
      WHERE child.workspace_id = #{workspaceId}
        AND child.deleted = false
    )
    SELECT id FROM subtree
  )



    ORDER BY d.updated_at ASC, d.id ASC


    ORDER BY d.created_at ASC, d.id ASC


    ORDER BY d.created_at DESC, d.id DESC


    ORDER BY d.updated_at DESC, d.id DESC


LIMIT #{limit} OFFSET #{offset}
